/// <summary>
/// AVA/WEN/2025/06/30       AVA_013359_RelocationLock
/// </summary>
/// <returns>boolean</returns>
public boolean canClose()
{
    boolean ret = next canClose();

    if (ret)
    {
        ret = !this.avaIsAgentReceiveLocked();
    }

    return ret;
}

/// <summary>
/// AVA/WEN/2025/06/30       AVA_013359_RelocationLock
/// </summary>
void closeOk()
{
    if (this.avaIsAgentReceiveLocked())
    {
        throw error("@NDX:NXAAgentReceiveLocked");
    }
    next closeOk();
}

/// <summary>
/// AVA/WEN/2025/06/30       AVA_013359_RelocationLock
/// </summary>
/// <returns>boolean</returns>
boolean avaIsAgentReceiveLocked()
{
    InventTransferParmTable inventTransferParmTableLocal;
    InventTransferTable     inventTransferTableLocal;
    InventLocation          locInventLocation;

    boolean  ret = false;

    while select inventTransferParmTableLocal
    where inventTransferParmTableLocal.ParmId == InventTransferParmUpdate.ParmId
    {
        inventTransferTableLocal                      = InventTransferTable::find(inventTransferParmTableLocal.TransferId);
        locInventLocation                           = InventLocation::find(inventTransferTableLocal.InventLocationIdTo);

        if (inventTransferTableLocal.KCS_TransferType == KCS_TransferType::Agent && locInventLocation.AVARelocationLocked)
        {
            ret = true;
            error(strFmt("@NDX:NXAAgentLocationLocked", locInventLocation.InventLocationId));
        }
    }

    return ret;
}
